pergunta:
quero que faça as seguintes alterações no  codigo abaixo:

SparseMatrix* sum(SparseMatrix* A, SparseMatrix* B);
Essa função recebe como parâmetro as matrizes A e B, devolvendo uma matriz C
que  é a soma de A e B.

SparseMatrix *multiply(SparseMatrix *A, SparseMatrix *B);
Essa fuņçao recebe como parametro as matrizes A e B, devolvendo uma matriz C
que é a multiplicação  de A por B.

---------------------------------------main------------------------------------

#include <iostream>
#include <fstream>
#include "SparseMatrix.h"

SparseMatrix *lerMatrizEsparsa(std::string nome_arquivo)
{
    std::ifstream arquivo(nome_arquivo);

    if (!arquivo)
    {
        std::cout << "Erro ao abrir o arquivo: " << nome_arquivo << std::endl;
        return nullptr;
    }

    int linhas, colunas;
    arquivo >> linhas >> colunas;

    SparseMatrix *matriz = new SparseMatrix(linhas, colunas);

    int linha, coluna;
    double valor;
    while (arquivo >> linha >> coluna >> valor)
    {
        matriz->inserir(linha, coluna, valor);
    }

    arquivo.close();
    return matriz;
}

SparseMatrix *soma(SparseMatrix *A, SparseMatrix *B)
{
    if (A->getLinhas() != B->getLinhas() || A->getColunas() != B->getColunas())
    {
        std::cout << "As matrizes devem ter as mesmas dimensões para realizar a soma." << std::endl;
        return nullptr;
    }

    SparseMatrix *resultado = new SparseMatrix(A->getLinhas(), A->getColunas());
    for (int i = 0; i < A->getLinhas(); i++)
    {
        for (int j = 0; j < A->getColunas(); j++)
        {
            double valorA = A->get(i, j);
            double valorB = B->get(i, j);
            resultado->inserir(i, j, valorA + valorB);
        }
    }

    return resultado;
}

SparseMatrix *multiplicacao(SparseMatrix *A, SparseMatrix *B)
{
    if (A->getColunas() != B->getLinhas())
    {
        std::cout << "O número de colunas da matriz A deve ser igual ao número de linhas da matriz B para realizar a multiplicação." << std::endl;
        return nullptr;
    }

    SparseMatrix *resultado = new SparseMatrix(A->getLinhas(), B->getColunas());
    for (int i = 0; i < A->getLinhas(); i++)
    {
        for (int j = 0; j < B->getColunas(); j++)
        {
            double valor = 0.0;
            for (int k = 0; k < A->getColunas(); k++)
            {
                valor += A->get(i, k) * B->get(k, j);
            }
            resultado->inserir(i, j, valor);
        }
    }

    return resultado;
}

int main()
{
    // Exemplo de uso
    SparseMatrix *A = lerMatrizEsparsa("matrixA.txt");
    SparseMatrix *B = lerMatrizEsparsa("matrixB.txt");

    if (A != nullptr && B != nullptr)
    {
        std::cout << "Matriz A:" << std::endl;
        A->imprimir();

        std::cout << "Matriz B:" << std::endl;
        B->imprimir();

        SparseMatrix *resultadoSoma = soma(A, B);
        if (resultadoSoma != nullptr)
        {
            std::cout << "Soma das matrizes:" << std::endl;
            resultadoSoma->imprimir();
            delete resultadoSoma;
        }

        SparseMatrix *resultadoMultiplicacao = multiplicacao(A, B);
        if (resultadoMultiplicacao != nullptr)
        {
            std::cout << "Multiplicação das matrizes:" << std::endl;
            resultadoMultiplicacao->imprimir();
            delete resultadoMultiplicacao;
        }
    }

    delete A;
    delete B;

    return 0;
}


