// Implementação da Soma
SparseMatrix *soma(SparseMatrix *A, SparseMatrix *B)
{
    if (A == nullptr || B == nullptr)
    {
        std::cout << "Uma ou ambas as matrizes são nulas." << std::endl;
        return nullptr;
    }

    if (A->getLinhas() != B->getLinhas() || A->getColunas() != B->getColunas())
    {
        std::cout << "As matrizes devem ter as mesmas dimensões para realizar a soma." << std::endl;
        return nullptr;
    }

    SparseMatrix *resultado = new SparseMatrix(A->getLinhas(), A->getColunas());

    int linhas = A->getLinhas();
    int colunas = A->getColunas();

    for (int i = 0; i < linhas; i++)
    {
        for (int j = 0; j < colunas; j++)
        {
            double valorA = A->get(i, j);
            double valorB = B->get(i, j);

            // Somamos os valores
            double soma = valorA + valorB;

            // Opcional: Em matrizes estritamente esparsas, não devemos salvar 0.0
