            }
            else 
            {
                // Não fazemos nada, pois o valor é zero e não deve estar na lista encadeada
            }
        }
    }

    return resultado;
}

// Implementação da Multiplicação
SparseMatrix *multiplicacao(SparseMatrix *A, SparseMatrix *B)
{
    if (A == nullptr || B == nullptr)
    {
        std::cout << "Uma ou ambas as matrizes são nulas." << std::endl;
        return nullptr;
    }

    if (A->getColunas() != B->getLinhas())
    {
        std::cout << "O número de colunas da matriz A deve ser igual ao número de linhas da matriz B para realizar a multiplicação." << std::endl;
        return nullptr;
    }

    SparseMatrix *resultado = new SparseMatrix(A->getLinhas(), B->getColunas());

    int linhasA = A->getLinhas();
    int colunasB = B->getColunas();
    int colunasA = A->getColunas(); // Usado no loop interno

    for (int i = 0; i < linhasA; i++)
    {
        for (int j = 0; j < colunasB; j++)
        {
            double valorTotal = 0.0;

            // Loop clássico da multiplicação matricial
            for (int k = 0; k < colunasA; k++)
            {
                double valA = A->get(i, k);
                double valB = B->get(k, j);

                // Otimização: Se qualquer termo for zero, o produto é zero, não precisa somar
                if (valA != 0.0 && valB != 0.0)
                {
                    valorTotal += valA * valB;
                }
            }

            // Só insere na matriz resultante se o resultado não for zero
            if (valorTotal != 0.0)
            {
                resultado->inserir(i, j, valorTotal);
            }
        }
    }

    return resultado;
}

