    Vector3 direction = ballPosition - pocketPosition;
    double radius = direction.length();

    // Evita divisão por zero se a bola já estiver extremamente próxima
    if (radius < 0.0001) return; 

    // Define o limite mínimo de raio antes de entrar na fase "direta"
    // Isso garante que a espiral termine suavemente antes de cortar reto
    double minSpiralRadius = speed * 0.5; 

